INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4191053', '1139 Ganja earthquake', 'The 1139 Ganja earthquake was one of the worst seismic events in history. It affected the Seljuk Empire and the Kingdom of Georgia, in modern-day Azerbaijan and Georgia.', 1139, NULL, NULL, NULL, NULL, NULL, 'year', '1139', 48, 'https://en.wikipedia.org/wiki/1139_Ganja_earthquake'),
  ('Q1048657', 'Battle of Shamkor', 'Battle of Shamkor (Georgian: შამქორის ბრძოლა) was fought on June 1, 1195, near the city of Shamkor, Arran. The battle was a major victory won by the Georgian army, commanded by David Soslan, over the army of the Eldiguzid ruler of Nusrat al-Din Abu Bakr.', 1195, 6, 1, NULL, NULL, NULL, 'day', '1 June 1195', 48, 'https://en.wikipedia.org/wiki/Battle_of_Shamkor'),
  ('Q107354947', 'Mongol invasions of Azerbaijan', 'The Mongol invasions and conquests of the territory that now comprises the Republic of Azerbaijan took place during the 13th and 14th centuries and involved large-scale raids. The Mongol invasions of Azerbaijan resulted in the incorporation of the territories of what now comprises Azerbaijan into the newly established Hulagu state.', 1220, NULL, NULL, 1356, NULL, NULL, 'year', '1220–1356', 30, 'https://en.wikipedia.org/wiki/Mongol_invasions_of_Azerbaijan'),
  ('Q42005', 'Black Death', 'The Black Death was a plague pandemic that occurred in Europe from 1346 to 1353. It was one of the most fatal pandemics in human history, leading to the death of up to 50 million people, around 30% to 60% of the European population and approximately 33% of the Middle Eastern population.', 1346, NULL, NULL, 1352, NULL, NULL, 'year', '1346–1352', 92, 'https://en.wikipedia.org/wiki/Black_Death'),
  ('Q4871847', 'Battle of Nakhchivan', 'The Battle of Nakhchivan (Persian: نبرد نخجوان) was fought between Kara Koyunlu under their Bey, Qara Yusuf and the Timurid Empire under the leadership of Timur''s grandson Abu Bakr Mirza ibn Miran Shah, for control of Azerbaijan on October 14, 1406. Qara Yusuf decisively defeated the Timurids in this battle and took over Tabriz, the capital of the region.', 1406, 10, 14, NULL, NULL, NULL, 'day', '14 October 1406', 39, 'https://en.wikipedia.org/wiki/Battle_of_Nakhchivan_(1406)'),
  ('Q12849799', 'Battle of Sharur', 'The Battle of Sharur was fought in 1501 near Sharur, close to Nakhchivan, between the forces of Ismail ibn Shaykh Haydar and the Aq Qoyunlu army of Alvand Mirza. Ismail decisively defeated Alvand, after which the Qizilbash advanced unopposed on Tabriz, the former Aq Qoyunlu imperial capital.', 1501, 7, 17, NULL, NULL, NULL, 'day', '17 July 1501', 39, 'https://en.wikipedia.org/wiki/Battle_of_Sharur'),
  ('Q6569289', 'Şahkulu Revolt', 'The Şahkulu rebellion was a widespread pro-Shia and pro-Safavid uprising in Anatolia, directed against the Ottoman Empire, in 1511. It began among the Turkmen tribes of the Taurus Mountains, before spreading to a wide variety of disgruntled groups.', 1511, 4, 9, 1511, 7, 2, 'day', '9 April 1511 – 2 July 1511', 47, 'https://en.wikipedia.org/wiki/%C5%9Eahkulu_rebellion'),
  ('Q16537286', 'Battle of Mollahasanli', 'The Battle of Mollahasanli took place on 28 November 1578 during the Ottoman–Safavid War (1578–1590) in the town of Mollahasanli on the banks of the Agsu River in Shirvan. The Safavid army, under the command of the Crown Prince Hamza Mirza, defeated the army of the Ottoman ally, the Crimean Khan, under the command of the kalga Adil Giray.', 1578, 11, 15, NULL, NULL, NULL, 'day', '15 November 1578', 37, 'https://en.wikipedia.org/wiki/Battle_of_Mollahasanli'),
  ('Q20473264', 'Siege of Ganja', 'The siege of Ganja (Persian: محاصره گنجه) took place in 1606 during the Ottoman–Safavid War of 1603–1618. The Safavids had lost the city to the Ottomans by the Treaty of Constantinople of 1590.', 1606, 4, NULL, 1606, 7, 5, 'month', 'April 1606 – 5 July 1606', 37, 'https://en.wikipedia.org/wiki/Siege_of_Ganja_(1606)'),
  ('Q18162521', 'Siege of Ganja', 'The siege of Ganja (Persian: محاصره گنجه), during the last phase of the Ottoman–Persian War (1730–1735), resulted in the surrender of the city by its Ottoman garrison after the main Turkish army marching to its relief was decisively defeated at the battle of Baghavard.', 1734, 11, 3, 1735, 7, 9, 'day', '3 November 1734 – 9 July 1735', 39, 'https://en.wikipedia.org/wiki/Siege_of_Ganja_(1734%E2%80%931735)'),
  ('Q2568851', 'Battle of Baku', 'The Battle of Baku (Azerbaijani: Bakı döyüşü, Turkish: Bakü Muharebesi, Russian: Битва за Баку) took place in August and September 1918 between the Ottoman–Azerbaijani coalition forces led by Nuri Pasha and Bolshevik–ARF Baku Soviet forces, later succeeded by the British–Armenian–White Russian forces led by Lionel Dunsterville, and saw Soviet Russia briefly re-enter the war. The battle took place during World War I, was a conclusive part of the Caucasus campaign, but a beginning of the Armenian–Azerbaijani War.', 1918, 8, 26, 1918, 9, 14, 'day', '26 August 1918 – 14 September 1918', 62, 'https://en.wikipedia.org/wiki/Battle_of_Baku'),
  ('Q7487589', 'Shamkhor Massacre', 'The Shamkhor massacre (Russian: Шамхорская резня) or the Shamkhor incident (Azerbaijani: Şamxor hadisəsi), took place on 22–25 January (9–12 January, Old Style) 1918, Shamkir, Azerbaijan. The Azerbaijani armed groups, acting on orders from the Military Council of Nationalities, massacred Russian soldiers who were returning home from the Caucasus Front, in an effort to obtain sufficient arms.', 1918, 1, NULL, NULL, NULL, NULL, 'month', 'January 1918', 37, 'https://en.wikipedia.org/wiki/Shamkhor_massacre'),
  ('Q31291891', 'Battle of Goychay', 'The Battle of Goychay (Azerbaijani: Göyçay döyüşü; Russian: Геокчайский бой; Turkish: Göyçay/Gökçay Savaşı) or Raid on Goychay (Azerbaijani: Göyçay basqını, Turkish: Göyçay/Gökçay Baskını), was a series of clashes that took place from 27 June to 1 July 1918, between Ottoman–Azerbaijani coalition forces led by Nuri Pasha and a coalition of the Soviet 11th Army and Armenian Dashnak forces. The initial battle ended on 30 June, but minor clashes continued until 1 July.', 1918, 7, 1, NULL, NULL, NULL, 'day', '1 July 1918', 43, 'https://en.wikipedia.org/wiki/Battle_of_Goychay'),
  ('Q381375', 'First Nagorno-Karabakh War', 'The First Nagorno-Karabakh War was an ethnic and territorial conflict that took place from February 1988 to May 1994 in the enclave of Nagorno-Karabakh in southwestern Azerbaijan between the majority ethnic Armenians of Nagorno-Karabakh backed by Armenia, and the Republic of Azerbaijan with support from Turkey. As the war progressed, Armenia and Azerbaijan, both former Soviet republics, entangled themselves in protracted, undeclared mountain warfare in the mountainous heights of Karabakh as Azerbaijan attempted to curb the Karabakh Movement.', 1988, 2, 20, 1994, 5, 16, 'day', '20 February 1988 – 16 May 1994', 80, 'https://en.wikipedia.org/wiki/First_Nagorno-Karabakh_War'),
  ('Q7493865', 'Siege of Stepanakert', 'The siege of Stepanakert started in late 1991, during the First Nagorno-Karabakh War, in Stepanakert, the largest city in Nagorno-Karabakh, when the Azerbaijani forces circled the city. Until May 1992, the city and its Armenian population were the target of a months-long campaign of bombardment by Azerbaijan.', 1991, 11, NULL, 1992, 5, 9, 'month', 'November 1991 – 9 May 1992', 41, 'https://en.wikipedia.org/wiki/Siege_of_Stepanakert'),
  ('Q2273348', 'Maraghar massacre', 'The Maraga massacre (Armenian: Մարաղայի կոտորած, romanized: Maraghayi kotorats) was the mass murder of Armenian civilians in the village of Maraga (Maragha) by Azerbaijani troops, which had captured the village on April 10, 1992, in the course of the First Nagorno-Karabakh War. The villagers, including men, women, children and elderly, were killed indiscriminately and deliberately, their houses were pillaged and burnt; the village was destroyed.', 1992, 4, 10, NULL, NULL, NULL, 'day', '10 April 1992', 57, 'https://en.wikipedia.org/wiki/Maraga_massacre'),
  ('Q2621289', 'Battle of Shusha', 'The Battle of Shusha (Codenamed: Operation Wedding in The Mountains; Armenian: Հարսանիք լեռներում, Harsaniq lernerum; Russian: Свадьба в горах, Svadba v gorakh) (Armenian: Շուշի, Shushi) was the first significant military victory by Armenian forces during the First Nagorno-Karabakh War. The battle took place in the strategically important mountain town of Shusha on the evening of 8 May 1992, and fighting swiftly concluded the next day after Armenian forces captured it and drove out the defending Azerbaijanis.', 1992, NULL, NULL, NULL, NULL, NULL, 'year', '1992', 53, 'https://en.wikipedia.org/wiki/Battle_of_Shusha_(1992)'),
  ('Q4562522', 'Capture of Garadaghly', 'The Capture of Garadaghly (Azerbaijani: Qaradağlının işğalı) was the seizure of Garadaghly, an Azerbaijani-populated village in Khojavend district of Nagorno-Karabakh by Armenian volunteer units on 17 February 1992, in the First Nagorno-Karabakh War.', 1992, 2, 17, NULL, NULL, NULL, 'day', '17 February 1992', 41, 'https://en.wikipedia.org/wiki/Capture_of_Garadaghly'),
  ('Q6743384', 'Malibeyli and Gushchular Massacre', 'The Capture of Gushchular and Malibeyli was an incident in which eight ethnic Azerbaijani civilians were killed by Armenian irregular armed units in simultaneous attacks on the villages of Malibeyli, Ashaghi Gushchular, and Yukhari Gushchular in the Shusha District of Azerbaijan, on February 10–12, 1992 during the First Nagorno-Karabakh War.', 1992, 2, 10, NULL, NULL, NULL, 'day', '10 February 1992', 39, 'https://en.wikipedia.org/wiki/Capture_of_Gushchular_and_Malibeyli'),
  ('Q629096', 'Battle of Kalbajar', 'The Battle of Kalbajar took place in March and April 1993, during the First Nagorno-Karabakh War. It resulted in the capture of the Kalbajar District of Azerbaijan by Armenian military forces.', 1993, 3, 27, 1993, 4, 3, 'day', '27 March 1993 – 3 April 1993', 51, 'https://en.wikipedia.org/wiki/Battle_of_Kalbajar'),
  ('Q4087293', 'Battle of Aghdam', 'The Battle of Aghdam (June – July 1993) took place on 23 July 1993 during the First Nagorno-Karabakh War, during which Armenian forces captured the Azerbaijani city of Aghdam. The city of Aghdam, which had about 50,000 inhabitants prior to its capture, is located about 30 km northeast of Stepanakert and 5 km east of the border of the former Nagorno-Karabakh Autonomous Oblast.', 1993, 7, 23, 1993, 7, 23, 'day', '23 July 1993', 41, 'https://en.wikipedia.org/wiki/Battle_of_Aghdam'),
  ('Q4832443', 'Azerbaijani vote of confidence referendum, 1993', 'A national vote of confidence in President Abulfaz Elchibey was held in Azerbaijan on 29 August 1993, following a coup d''état in June by Surat Huseynov. Voters were asked if they trusted the President of the Azerbaijan Republic.', 1993, 8, 29, NULL, NULL, NULL, 'day', '29 August 1993', 41, 'https://en.wikipedia.org/wiki/1993_Azerbaijani_vote_of_confidence_referendum'),
  ('Q20744392', '1993 Azerbaijani coup d''état', 'The 1993 Azeri coup d''état, also known as the Ganja Uprising, was a military coup led by Azerbaijani military commander Surat Huseynov. On June 4, 1993, Huseynov''s forces led a march from the city of Ganja to the Azerbaijani capital of Baku in order to overthrow President Abulfaz Elchibey who was elected in independent Azerbaijan''s first free election in 1992.', 1993, 9, 1, NULL, NULL, NULL, 'day', '1 September 1993', 50, 'https://en.wikipedia.org/wiki/1993_Azerbaijani_coup_d''%C3%A9tat'),
  ('Q4087310', 'Operation Kalbajar', 'Operation Kalbajar was a military offensive launched by the Azerbaijani Armed Forces in late 1993 against the forces of the Armenian Army and the self-proclaimed Nagorno-Karabakh Republic to recapture the district of Kalbajar in the final stage of the First Nagorno-Karabakh War. Armenian forces had captured the entire district in an offensive in March–April 1993.', 1994, NULL, NULL, NULL, NULL, NULL, 'year', '1994', 39, 'https://en.wikipedia.org/wiki/Operation_Kalbajar'),
  ('Q12840374', 'Operation Horadiz', 'Operation Horadiz (Azerbaijani: Horadiz əməliyyatı) was a battle during the First Nagorno-Karabakh War between the Azerbaijani Armed Forces and the Armenian Armed Forces in Horadiz village of Fuzuli District of the Republic of Azerbaijan, which began in December 1993 and lasted until January 6.', 1994, 1, 6, NULL, NULL, NULL, 'day', '6 January 1994', 41, 'https://en.wikipedia.org/wiki/Operation_Horadiz'),
  ('Q16662578', 'Azerbaijan Airlines Flight 56', 'Azerbaijan Airlines Flight A-56 was a scheduled domestic passenger flight operated by Azerbaijan Airlines, from Nakhchivan Airport to Baku, which crashed whilst attempting an emergency landing on 5 December 1995, killing 52 out of the 82 people on board. The twin-engine aircraft operating the flight, a Tupolev Tu-134, experienced an engine failure shortly after take-off, but the second engine that was operable was shut down in error.', 1995, 12, 5, NULL, NULL, NULL, 'day', '5 December 1995', 51, 'https://en.wikipedia.org/wiki/Azerbaijan_Airlines_Flight_A-56'),
  ('Q4597199', '2000 Baku earthquake', 'On 25 November 2000, at 22:09 (18:09 AZT), a Mw 6.8 earthquake struck with an epicenter just offshore Baku, Azerbaijan. It was followed a minute later by a Mw 6.5 event.', 2000, 11, 25, NULL, NULL, NULL, 'day', '25 November 2000', 50, 'https://en.wikipedia.org/wiki/2000_Baku_earthquake'),
  ('Q4272123', 'Azerbaijani constitutional referendum', 'A constitutional referendum was held in Azerbaijan on 24 August 2002. The referendum was initiated by the authoritarian Heydar Aliyev regime.', 2002, 8, 24, NULL, NULL, NULL, 'day', '24 August 2002', 41, 'https://en.wikipedia.org/wiki/2002_Azerbaijani_constitutional_referendum'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q4832380', 'Azerbaijan Airlines Flight 217', 'Azerbaijan Airlines Flight 217 was a scheduled passenger flight between Baku and Aktau, Kazakhstan that crashed into the Caspian Sea at ca. 22:40 on 23 December 2005.', 2005, 12, 23, NULL, NULL, NULL, 'day', '23 December 2005', 52, 'https://en.wikipedia.org/wiki/Azerbaijan_Airlines_Flight_217'),
  ('Q1754030', '2008 Mardakert skirmishes', 'The 2008 Mardakert clashes began on March 4 after the 2008 Armenian election protests. It involved the heaviest fighting between ethnic Armenian and Azerbaijani forces over the disputed region of Nagorno-Karabakh since the 1994 ceasefire after the First Nagorno-Karabakh War.', 2008, 3, 4, 2008, 3, 4, 'day', '4 March 2008', 47, 'https://en.wikipedia.org/wiki/2008_Mardakert_clashes'),
  ('Q1753755', '2010 Mardakert skirmishes', 'The 2010 Mardakert clashes were a series of violations of the First Nagorno-Karabakh War ceasefire. They took place across the line of contact dividing Azerbaijan and the ethnic Armenian military forces of the unrecognized but de facto independent Nagorno-Karabakh Republic.', 2010, 9, 1, NULL, NULL, NULL, 'day', '1 September 2010', 47, 'https://en.wikipedia.org/wiki/2010_Mardakert_clashes'),
  ('Q189079', 'Van earthquake of 2011', 'The 2011 Van earthquakes occurred in eastern Turkey near the city of Van. The first earthquake happened on 23 October at 13:41 local time.', 2011, 10, 23, NULL, NULL, NULL, 'day', '23 October 2011', 70, 'https://en.wikipedia.org/wiki/2011_Van_earthquakes'),
  ('Q17480419', '2014 Armenian–Azerbaijani clashes', 'Clashes on the Armenian–Azerbaijan border (Tavush–Qazakh) and the line of contact between the Nagorno-Karabakh and Azerbaijan started on 27 July 2014. Reported casualties of the clashes were some of the highest since the 1994 ceasefire agreement that ended the First Nagorno-Karabakh War.', 2014, 8, 8, 2014, 8, 8, 'day', '8 August 2014', 47, 'https://en.wikipedia.org/wiki/2014_Armenian%E2%80%93Azerbaijani_clashes'),
  ('Q19944579', '2015 Baku residence building fire', 'The 2015 Baku residence building fire occurred on 19 May 2015 in a 16-level residence building located at Azadlig Avenue 200/36 in Binagadi raion of Baku, Azerbaijan. The official death toll from the fire was 15, of whom five were children; at least 63 people were injured.', 2015, 5, 19, NULL, NULL, NULL, 'day', '19 May 2015', 41, 'https://en.wikipedia.org/wiki/2015_Baku_residence_building_fire'),
  ('Q23688698', '2016 Nagorno-Karabakh conflict', 'The 2016 Nagorno-Karabakh conflict, also known as the Four-Day War, April War, or April clashes, began along the former Nagorno-Karabakh line of contact on 1 April 2016 with the Artsakh Defence Army, backed by the Armenian Armed Forces, on one side and the Azerbaijani Armed Forces on the other. The clashes occurred in a region that is disputed between the self-proclaimed Republic of Artsakh and the Republic of Azerbaijan.', 2016, 4, 2, 2016, 4, 5, 'day', '2 April 2016 – 5 April 2016', 65, 'https://en.wikipedia.org/wiki/2016_Nagorno-Karabakh_conflict'),
  ('Q26868901', '2016 Azerbaijani constitutional referendum', 'A constitutional referendum was held in Azerbaijan on 26 September 2016. Voters were asked whether they approved of 29 constitutional amendments, with a separate vote on each one.', 2016, 9, 26, NULL, NULL, NULL, 'day', '26 September 2016', 50, 'https://en.wikipedia.org/wiki/2016_Azerbaijani_constitutional_referendum'),
  ('Q54448834', '2018 Armenian–Azerbaijani clashes', 'The 2018 Armenian–Azerbaijani clashes began on 20 May 2018 between the Armenian Armed Forces and Azerbaijani Armed Forces. Azerbaijan stated to have taken several villages and strategic positions within the Nakhchivan Autonomous Republic.', 2018, 5, 20, 2018, 5, 27, 'day', '20 May 2018 – 27 May 2018', 47, 'https://en.wikipedia.org/wiki/2018_Armenian%E2%80%93Azerbaijani_clashes'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q97303396', 'July 2020 Armenian–Azerbaijani clashes', 'The July 2020 Armenian–Azerbaijani clashes began on 12 July 2020 between the Armenian Armed Forces and Azerbaijani Armed Forces. Initial clashes occurred near Movses in Tavush Province of Armenia, and Ağdam in Tovuz District of Azerbaijan at the Armenian–Azerbaijani state border.', 2020, 7, 12, 2020, 7, NULL, 'day', '12 July 2020 – July 2020', 60, 'https://en.wikipedia.org/wiki/July_2020_Armenian%E2%80%93Azerbaijani_clashes'),
  ('Q99659280', 'Second Nagorno-Karabakh War', 'The Second Nagorno-Karabakh War was an armed conflict in 2020 that took place in the disputed region of Nagorno-Karabakh and the surrounding occupied territories. It was a major escalation of an unresolved conflict over the region, involving Azerbaijan, Armenia and the self-declared Armenian breakaway state of Artsakh.', 2020, NULL, NULL, 2020, 11, 10, 'year', '2020', 81, 'https://en.wikipedia.org/wiki/Second_Nagorno-Karabakh_War'),
  ('Q100606474', 'Battle of Hadrut', 'The Battle of Hadrut (Azerbaijani: Hadrut döyüşü; Armenian: Հադրութի ճակատամարտ, romanized: Hadrut’i chakatamart) began in early October 2020 in Hadrut and its surrounding villages and heights, now seat of Khojavend District, Azerbaijan, and earlier controlled by the self-proclaimed Republic of Artsakh and was part of Hadrut Province. Following Azerbaijan''s capture of the city of Jabrayil, and claiming full dominance of the district of the same name, the Azerbaijani forces advanced north, to Hadrut.', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 43, 'https://en.wikipedia.org/wiki/Battle_of_Hadrut'),
  ('Q101305942', 'Battle of Shusha', 'The Battle of Shusha (Azerbaijani: Şuşa döyüşü or Şuşa uğrunda döyüş; Armenian: Շուշիի ճակատամարտ, romanized: Shushii chakatamart) was the final and decisive battle of the Second Nagorno-Karabakh War, fought between the armed forces of Azerbaijan and the self-proclaimed Republic of Artsakh, militarily supported by Armenia, over the control of the city of Shusha. The battle is considered one of the bloodiest battles of the war.', 2020, 11, NULL, NULL, NULL, NULL, 'month', 'November 2020', 60, 'https://en.wikipedia.org/wiki/Battle_of_Shusha_(2020)'),
  ('Q101429497', '2020 Nagorno-Karabakh ceasefire agreement', 'The 2020 Nagorno-Karabakh ceasefire agreement was an armistice agreement that ended the Second Nagorno-Karabakh War. It was signed on 9 November by the President of Azerbaijan Ilham Aliyev, the Prime Minister of Armenia Nikol Pashinyan and the President of Russia Vladimir Putin, and ended all hostilities in the Nagorno-Karabakh region from 00:00, on 10 November 2020 Moscow time.', 2020, 11, 9, NULL, NULL, NULL, 'day', '9 November 2020', 69, 'https://en.wikipedia.org/wiki/2020_Nagorno-Karabakh_ceasefire_agreement'),
  ('Q101925544', 'Aras Valley campaign', 'The Aras Valley campaign (Azerbaijani: Araz vadisi əməliyyatları, Armenian: Արասի հովտի արշավ, romanized: Arasi hovti arshav) was a military operation launched by Azerbaijan against the breakaway Republic of Artsakh along the Aras River in the Azerbaijan–Iran border during the Second Nagorno-Karabakh War. The operations started on 27 September, with Azerbaijani advancements in Jabrayil and Fuzuli districts, with the initial objective to seize control of Jabrayil and Füzuli.', 2020, 9, 27, 2020, 11, 10, 'day', '27 September 2020 – 10 November 2020', 37, 'https://en.wikipedia.org/wiki/Aras_Valley_campaign'),
  ('Q102423003', 'Madagiz offensive', 'The Madagiz offensive, also called the Battle of Madagiz (Azerbaijani: Madagiz döyüşü; Armenian: Մատաղիսի ճակատամարտ, romanized: Mataghisi chakatamart), or the Battle of Sugovushan (Azerbaijani: Suqovuşan döyüşü), was a military operation launched by Azerbaijan against the self-proclaimed Republic of Artsakh and their Armenian allies during the Second Nagorno-Karabakh War. The offensive began on 28 September, when the Azerbaijani forces advanced towards Armenian positions near the abandoned village of Talish.', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 43, 'https://en.wikipedia.org/wiki/Madagiz_offensive'),
  ('Q113404565', 'August 2022 Nagorno-Karabakh clashes', 'The military forces of Armenia and Azerbaijan have been engaged in a border conflict since 12 May 2021, when Azerbaijani soldiers crossed several kilometers into Armenia in the provinces of Syunik and Gegharkunik. Despite international calls for withdrawal from the European Parliament, France, Iran, and the United States, Azerbaijan has maintained its presence on Armenian soil, occupying at least 215 square kilometers (83 sq mi) of internationally recognized Armenian territory.', 2022, 8, 3, NULL, NULL, NULL, 'day', '3 August 2022', 37, 'https://en.wikipedia.org/wiki/August_2022_Nagorno-Karabakh_clashes'),
  ('Q122700456', '2023 Azerbaijani offensive in Nagorno-Karabakh', 'On 19 and 20 September 2023, Azerbaijan launched a large-scale military offensive against the self-declared breakaway state of Artsakh, violating the ceasefire agreement signed in the aftermath of the Second Nagorno-Karabakh War in 2020. The offensive took place in the disputed region of Nagorno-Karabakh, which is de jure a part of Azerbaijan, and was a de facto independent republic.', 2023, 9, NULL, 2023, 9, 20, 'month', 'September 2023 – 20 September 2023', 72, 'https://en.wikipedia.org/wiki/2023_Azerbaijani_offensive_in_Nagorno-Karabakh'),
  ('Q122819143', 'Nagorno-Karabakh fuel depot explosion', 'On 25 September 2023, at about 19:00 (UTC+4), an explosion occurred at a military fuel depot in Berkadzor near Stepanakert, in the region of Nagorno-Karabakh, resulting in the deaths of at least 218 people and 120 injuries. The explosion occurred amidst the chaotic exodus of Armenians from Nagorno-Karabakh to Armenia, following a major military offensive launched by Azerbaijan against the unrecognized Republic of Artsakh.', 2023, 9, 25, NULL, NULL, NULL, 'day', '25 September 2023', 47, 'https://en.wikipedia.org/wiki/Berkadzor_fuel_depot_explosion'),
  ('Q133821305', 'Armenia-Azerbaijan peace agreement', 'The Armenia–Azerbaijan peace deal, officially titled the Agreement "On the Establishment of Peace and Interstate Relations between the Republic of Armenia and the Republic of Azerbaijan", aims to end the ongoing Nagorno-Karabakh conflict between Armenia and Azerbaijan. On 8 August 2025, Armenian prime minister Nikol Pashinyan and Azerbaijani president Ilham Aliyev, with the mediation of United States president Donald Trump, initialed an agreement and signed a joint declaration emphasizing the need to continue efforts toward the signing and final ratification of the agreement.', 2025, 8, 8, NULL, NULL, NULL, 'day', '8 August 2025', 63, 'https://en.wikipedia.org/wiki/Armenia%E2%80%93Azerbaijan_peace_agreement');
